package javiertorres.amazonconbackend22settembre.controller;
import javiertorres.amazonconbackend22settembre.dto.OggettoAdminDto; import javiertorres.amazonconbackend22settembre.dto.OggettoPublicDto; import javiertorres.amazonconbackend22settembre.dto.OggettoRequest; import javiertorres.amazonconbackend22settembre.service.OggettoService; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/oggetti") public class OggettoController { private final OggettoService service; public OggettoController(OggettoService s){service=s;} @GetMapping public Object list(org.springframework.security.core.Authentication authentication){return authentication != null && authentication.getAuthorities().stream().anyMatch(a -> a.getAuthority().equals("ROLE_ADMIN")) ? service.all() : service.publicList();} @GetMapping("/{id}") public OggettoPublicDto get(@PathVariable UUID id){return service.publicOne(id);} @PostMapping @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.CREATED) public OggettoAdminDto create(@Valid @RequestBody OggettoRequest x){return service.create(x);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.delete(id);} @PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") public OggettoAdminDto update(@PathVariable UUID id,@Valid @RequestBody OggettoRequest x){return service.update(id,x);}}
